cd /tmp/e2e && cat > jsdom-check.mjs <<'EOF'
import { JSDOM } from 'jsdom';

const WS = '/home/sandbox/workspace';
const dom = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>', {
  url: 'http://localhost:5180/',
  pretendToBeVisual: true,
});
const { window } = dom;
// Globals the app / Gravity expect from a browser
const g = globalThis;
for (const k of ['window', 'document', 'navigator', 'localStorage', 'HTMLElement', 'HTMLInputElement', 'Event', 'KeyboardEvent', 'MouseEvent', 'Node', 'getComputedStyle', 'requestAnimationFrame', 'cancelAnimationFrame']) {
  if (!(k in g) || k === 'window') g[k] = window[k];
}
g.window = window; g.document = window.document; g.localStorage = window.localStorage;
g.navigator = window.navigator; g.HTMLElement = window.HTMLElement; g.getComputedStyle = window.getComputedStyle.bind(window);
g.IS_REACT_ACT_ENVIRONMENT = true;
window.matchMedia = window.matchMedia || (() => ({ matches: false, media: '', addEventListener() {}, removeEventListener() {}, addListener() {}, removeListener() {} }));
g.matchMedia = window.matchMedia;
if (!window.ResizeObserver) window.ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
g.ResizeObserver = window.ResizeObserver;

const { createServer } = await import(`${WS}/node_modules/vite/dist/node/index.js`);
const React = await import(`${WS}/node_modules/react/index.js`);
const { createRoot } = await import(`${WS}/node_modules/react-dom/client.js`);
const { act } = await import(`${WS}/node_modules/react/index.js`).then((m) => ({ act: m.act ?? m.default?.act }));

const server = await createServer({
  root: WS,
  configFile: `${WS}/vite.config.ts`,
  server: { middlewareMode: true, hmr: false },
  appType: 'custom',
  logLevel: 'error',
});
const mod = await server.ssrLoadModule('/src/App.tsx');
const { App } = mod;

const container = window.document.getElementById('root');
const root = createRoot(container);
await act(async () => root.render(React.createElement(App)));

const results = [];
const check = (name, cond) => { results.push(cond); console.log(`${cond ? 'PASS' : 'FAIL'} ${name}`); };
const tick = () => act(async () => { await new Promise((r) => setTimeout(r, 30)); });
const $ = (sel) => window.document.querySelector(sel);
const $$ = (sel) => [...window.document.querySelectorAll(sel)];
const text = () => window.document.body.textContent;
const byText = (sel, t) => $$(sel).find((el) => el.textContent.trim() === t);
const click = async (el) => { await act(async () => { el.dispatchEvent(new window.MouseEvent('click', { bubbles: true, cancelable: true })); }); await tick(); };
const setInput = async (el, value) => {
  await act(async () => {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, value);
    el.dispatchEvent(new window.Event('input', { bubbles: true }));
  });
  await tick();
};
const hashNav = async (hash) => { await act(async () => { window.location.hash = hash; }); await tick(); await tick(); };

// ---- Home (no hash) ----
check('home heading rendered', $('h1')?.textContent.includes('Добро пожаловать'));
check('default theme is light (matchMedia=light)', !window.document.body.className.includes('theme_dark'));
console.log('body class:', window.document.body.className);

// ---- nav to tasks via header nav link ----
const navTasks = $$('nav[aria-label="Основная навигация"] a').find((a) => a.textContent === 'Задачи');
check('nav links are anchors with hash href', navTasks?.getAttribute('href') === '#/tasks');
await click(navTasks);
await tick();
check('clicking Задачи nav link sets hash', window.location.hash === '#/tasks');
check('tasks page heading shown', $('h1')?.textContent === 'Задачи');
check('aria-current=page on active link', $('nav a[aria-current="page"]')?.textContent === 'Задачи');

// ---- add tasks ----
const input = $('input[placeholder="Что нужно сделать?"]');
await setInput(input, 'Купить молоко');
const form = $('form');
await act(async () => { form.dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true })); });
await tick();
check('task 1 added', text().includes('Купить молоко'));
check('input cleared after add', $('input[placeholder="Что нужно сделать?"]').value === '');
await setInput($('input[placeholder="Что нужно сделать?"]'), '   ');
await act(async () => { form.dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true })); });
await tick();
check('blank task rejected', $$('label').length === 1);
await setInput($('input[placeholder="Что нужно сделать?"]'), 'Написать отчёт');
await act(async () => { form.dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true })); });
await tick();
check('task 2 added', text().includes('Написать отчёт'));
check('counter "Осталось: 2 из 2"', text().includes('Осталось: 2 из 2'));
check('localStorage app-tasks has 2 tasks', JSON.parse(localStorage.getItem('app-tasks')).length === 2);

// ---- toggle done ----
const cb = $$('input[type="checkbox"]')[0];
await click(cb);
check('checkbox toggled -> counter 1 of 2', text().includes('Осталось: 1 из 2'));
check('done state persisted to localStorage', JSON.parse(localStorage.getItem('app-tasks'))[0].done === true);

// ---- delete ----
const delBtn = $$('button').find((b) => b.textContent === 'Удалить');
await click(delBtn);
check('delete removes first task', !text().includes('Купить молоко') && text().includes('Написать отчёт'));
check('counter after delete "Осталось: 1 из 1"', text().includes('Осталось: 1 из 1'));

// ---- navigate away & back keeps state ----
await hashNav('#/about');
check('about page shown via hash', $('h1')?.textContent === 'О приложении');
check('back to tasks keeps task', (await (async () => { await hashNav('#/tasks'); return text().includes('Написать отчёт'); })()));

// ---- theme toggle ----
const sw = $$('label').find((l) => l.textContent.includes('Тёмная тема'));
const swInput = sw.querySelector('input');
await click(swInput);
check('dark class on body after switch', window.document.body.className.includes('theme_dark'));
check('localStorage app-theme=dark', localStorage.getItem('app-theme') === 'dark');
check('switch checked in dark', swInput.checked === true);

// Re-mount simulating reload: stored theme wins
root.unmount();
const root2 = createRoot(container);
await act(async () => root2.render(React.createElement(App)));
await tick();
check('dark theme restored from localStorage on new mount', window.document.body.className.includes('theme_dark'));
check('tasks restored from localStorage on new mount', text().includes('Написать отчёт'));

// toggle back to light
const swInput2 = $$('label').find((l) => l.textContent.includes('Тёмная тема')).querySelector('input');
await click(swInput2);
check('light again after toggle', !window.document.body.className.includes('theme_dark'));
check('localStorage app-theme=light', localStorage.getItem('app-theme') === 'light');

// direct hash load of unknown route falls back to home
window.history.replaceState(null, '', '#/nope');
root2.unmount();
const root3 = createRoot(container);
await act(async () => root3.render(React.createElement(App)));
await tick();
check('unknown hash falls back to home', $('h1')?.textContent.includes('Добро пожаловать'));

const passed = results.filter(Boolean).length;
console.log(`\n${passed}/${results.length} checks passed`);
await server.close();
process.exit(passed === results.length ? 0 : 1);
EOF
